"""One source-clock viewer for both camera tracks and explicit handoff gaps."""
import json
import os
from pathlib import Path
from urllib.parse import quote
from .end_view import export_end_views


def write_report(result, output, video, *, stone_detector=None, stone_colour_model=None):
    output=Path(output)
    result=dict(result)
    if result.get('match_observation_run'):
        directory=Path(result['match_observation_run'])/'match-view-data'
        manifest=directory/'manifest.json'
        if not manifest.exists():raise ValueError('Missing synchronized match observation manifest')
        manifest_data=json.loads(manifest.read_text())
        if manifest_data['source_sha256']!=result['source_sha256']:raise ValueError('Match observation viewer source mismatch')
        result['match_observation_display']={'directory':quote(os.path.relpath(directory.resolve(),output.resolve())),
            'manifest':manifest_data,'physical_end_identity_verified':False}
    result['end_views']=export_end_views(result['events'],video,output,stone_detector=stone_detector,
                                       observation_run=result.get('match_observation_run'),stone_colour_model=stone_colour_model)
    (output/'end-views.json').write_text(json.dumps(result['end_views'],indent=2)+'\n')
    data=json.dumps(result,allow_nan=False).replace('<','\\u003c')
    url=quote(os.path.relpath(Path(video).resolve(),output.resolve()))
    (output/'index.html').write_text(TEMPLATE.replace('__DATA__',data).replace('__VIDEO__',url))


